#nullable enable
using Alba;
using HourBooking.Contracts;
using HourBooking.Slices.Booking;
using Shouldly;
using Xunit;

namespace HourBooking.IntegrationTests.Slices.Booking;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation — which is the only reason these
/// tests mean anything. Pattern: command. Status: in-progress. LIVE: this slice is claimed, so every
/// test here must pass.
///
/// Ten GWTs, ten tests, in the order the model draws them. Membership comes from SeedData; the month
/// lifecycle comes from each test's own GIVEN.
/// </summary>
public sealed class BookHoursTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static string Timesheet => BookHoursState.StreamKey(SeedData.EmployeeId, SeedData.Month);
    private static string MonthClosure => MonthGate.StreamKey(SeedData.EmployeeId, SeedData.Month);

    private static BookingMonthStarted MonthOpened =>
        new(SeedData.EmployeeId, SeedData.EmployeeName, SeedData.Month, SeedData.SeededAt);

    /// <summary>WHEN BookHours — the request the screen makes, with a freshly minted bookingId.</summary>
    private Task<IScenarioResult> Book(
        DateOnly date, decimal hours, Guid? projectId = null, Guid? bookingId = null, string? note = null)
        => Post(new BookHours(
            bookingId ?? Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month,
            projectId ?? SeedData.ProjectId, date, hours, note));

    private async Task<IScenarioResult> Post(BookHours command)
    {
        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(command)
                .ToUrl($"/timesheet/{SeedData.EmployeeId}/{SeedData.Month}/bookings");
            // Each test asserts its own status; Alba would otherwise insist on 200.
            x.IgnoreStatusCode();
        });
        return result;
    }

    // hours can be booked on a project the employee belongs to, in an open month
    //   GIVEN BookingMonthStarted, EmployeeAssignedToProject
    //   WHEN  BookHours
    //   THEN  HoursBooked
    [Fact]
    public async Task HoursCanBeBookedOnAProjectTheEmployeeBelongsToIn()
    {
        await Given(MonthClosure, MonthOpened);

        var result = await Book(SeedData.WorkingDay, 7.5m);

        result.Context.Response.StatusCode.ShouldBe(204);
        var booked = (await EventsFor(Timesheet)).OfType<HoursBooked>().ShouldHaveSingleItem();
        booked.EmployeeId.ShouldBe(SeedData.EmployeeId);
        booked.ProjectId.ShouldBe(SeedData.ProjectId);
        booked.Date.ShouldBe(SeedData.WorkingDay);
        booked.Hours.ShouldBe(7.5m);
        booked.Month.ShouldBe(SeedData.Month);
    }

    // a date in the future is allowed — employees may prefill
    [Fact]
    public async Task ADateInTheFutureIsAllowedEmployeesMayPrefill()
    {
        await Given(MonthClosure, MonthOpened);

        var result = await Book(SeedData.SecondWorkingDay, 8m);

        result.Context.Response.StatusCode.ShouldBe(204);
        (await EventsFor(Timesheet)).OfType<HoursBooked>().ShouldHaveSingleItem()
            .Date.ShouldBe(SeedData.SecondWorkingDay);
    }

    // a date in the past is allowed within the open month
    [Fact]
    public async Task ADateInThePastIsAllowedWithinTheOpenMonth()
    {
        await Given(MonthClosure, MonthOpened);

        var past = new DateOnly(2026, 8, 1);
        var result = await Book(past, 8m);

        result.Context.Response.StatusCode.ShouldBe(204);
        (await EventsFor(Timesheet)).OfType<HoursBooked>().ShouldHaveSingleItem().Date.ShouldBe(past);
    }

    // zero hours is not a booking — removal is the only way to take a line back
    //   THEN error: HoursMustBeNonZero        enforce="periphery" -> the validator, before any stream
    [Fact]
    public async Task ZeroHoursIsNotABookingRemovalIsTheOnlyWayTo()
    {
        await Given(MonthClosure, MonthOpened);

        var result = await Book(SeedData.WorkingDay, 0m);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).ShouldBeEmpty();
    }

    // hours are booked in whole or half hours only
    //   THEN error: HoursMustBeWholeOrHalf    enforce="periphery"
    [Fact]
    public async Task HoursAreBookedInWholeOrHalfHoursOnly()
    {
        await Given(MonthClosure, MonthOpened);

        var result = await Book(SeedData.WorkingDay, 7.25m);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).ShouldBeEmpty();
    }

    // a closed month cannot be booked into — closed is closed
    //   GIVEN MonthClosed  THEN error: MonthIsClosed
    [Fact]
    public async Task AClosedMonthCannotBeBookedIntoClosedIsClosed()
    {
        await Given(MonthClosure, MonthOpened,
            new MonthClosed(SeedData.EmployeeId, SeedData.Month, SeedData.AdminId, null, SeedData.SeededAt));

        var result = await Book(SeedData.WorkingDay, 8m);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).ShouldBeEmpty();
    }

    // hours cannot be booked to a project the employee has left, and NOTHING is persisted
    //   GIVEN EmployeeRemovedFromProject  THEN error: NotAProjectMember
    [Fact]
    public async Task HoursCannotBeBookedToAProjectTheEmployeeHasLeftAnd()
    {
        await Given(MonthClosure, MonthOpened);

        // SeedData leaves the employee off LeftProjectId, which is the GIVEN for this rule.
        var result = await Book(SeedData.WorkingDay, 8m, projectId: SeedData.LeftProjectId);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).ShouldBeEmpty();
    }

    // at most 18 hours can stand for one day
    //   THEN error: DailyCapExceeded — an invariant only because the stream is per (employee, month)
    [Fact]
    public async Task AtMost18HoursCanStandForOneDay()
    {
        await Given(MonthClosure, MonthOpened);
        await Given(Timesheet, new HoursBooked(
            Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month, SeedData.ProjectId,
            SeedData.WorkingDay, 12m, null, SeedData.SeededAt));

        // 12 already standing + 7 asked for = 19, over the cap of 18. A different project, so the
        // once-per-day+project rule is not what refuses it.
        var result = await Book(SeedData.WorkingDay, 7m, projectId: SeedData.LeftProjectId);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).OfType<HoursBooked>().Count().ShouldBe(1);
    }

    // a day+project can only be BOOKED once — booking it again is a correction, not a booking
    //   GIVEN HoursBooked  THEN error: AlreadyBookedUseCorrection
    [Fact]
    public async Task ADayProjectCanOnlyBeBOOKEDOnceBookingItAgainIs()
    {
        await Given(MonthClosure, MonthOpened);
        await Given(Timesheet, new HoursBooked(
            Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month, SeedData.ProjectId,
            SeedData.WorkingDay, 4m, null, SeedData.SeededAt));

        var result = await Book(SeedData.WorkingDay, 4m);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).OfType<HoursBooked>().Count().ShouldBe(1);
    }

    // a submitted month is still open, so it can still be booked into until an admin closes it
    //   GIVEN MonthClosureSubmitted  THEN HoursBooked
    [Fact]
    public async Task ASubmittedMonthIsStillOpenSoItCanStillBeBooked()
    {
        await Given(MonthClosure, MonthOpened,
            new MonthClosureSubmitted(SeedData.EmployeeId, SeedData.Month, SeedData.SeededAt));

        var result = await Book(SeedData.WorkingDay, 8m);

        result.Context.Response.StatusCode.ShouldBe(204);
        (await EventsFor(Timesheet)).OfType<HoursBooked>().ShouldHaveSingleItem();
    }

    // NOT a GWT. The model says the Timesheet screen displays ten attributes, so a slice whose
    // screen cannot read back what it wrote is not done end to end. Reads belong to my-timesheet,
    // which is still in-design; this asserts the round trip the screen depends on, no more.
    [Fact]
    public async Task TheScreenCanReadBackWhatItBooked()
    {
        await Given(MonthClosure, MonthOpened);
        await Book(SeedData.WorkingDay, 7.5m);

        var sheet = await Host.Scenario(x =>
            x.Get.Url($"/timesheet/{SeedData.EmployeeId}/{SeedData.Month}"));
        var body = await sheet.ReadAsTextAsync();

        // The inline projection ran in the same transaction as the append, so it is already there.
        body.ShouldContain("\"monthStatus\": \"Open\"", Case.Insensitive);
        body.ShouldContain("7.5");

        var projects = await Host.Scenario(x =>
            x.Get.Url($"/timesheet/{SeedData.EmployeeId}/projects"));
        var list = await projects.ReadAsTextAsync();
        list.ShouldContain("Apollo");   // the name the screen joins on projectId
        list.ShouldContain("Gemini");   // left, and flagged rather than hidden
    }
}
